frappe.ui.form.on("Sales Order", {
    refresh(frm) {

        frm.set_query("custom_feasibility", "items", function(doc, cdt, cdn) {

            return {
                query: "nexapp.api.get_feasibility_list",
                filters: {
                    customer: doc.customer || "",
                    order_type: doc.order_type || ""
                }
            };
        });

    }
});

frappe.ui.form.on('Feasiblity Partner', {
    refresh: function (frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Create Supplier'), function () {
                // Check if a supplier already exists
                frappe.call({
                    method: 'frappe.client.get_list',
                    args: {
                        doctype: 'Supplier',
                        filters: { supplier_name: frm.doc.supplier },
                        limit_page_length: 1
                    },
                    callback: function (r) {
                        if (r.message.length > 0) {
                            frappe.msgprint(__('Supplier already created'), 'Warning');
                        } else {
                            // Create new Supplier
                            frappe.call({
                                method: 'frappe.client.insert',
                                args: {
                                    doc: {
                                        doctype: 'Supplier',
                                        supplier_name: frm.doc.supplier,
                                        supplier_group: frm.doc.supplier_group,
                                        supplier_type: frm.doc.supplier_type
                                    }
                                },
                                callback: function (res) {
                                    if (res.message) {
                                        frappe.show_alert({ message: __('Supplier Created'), indicator: 'green' });

                                        // Update status field in Feasibility Partner silently
                                        frappe.db.set_value('Feasiblity Partner', frm.doc.name, 'status', 'Supplier Created')
                                            .then(() => frm.reload_doc()); // Refresh form after update

                                        // Redirect to the newly created Supplier record
                                        frappe.set_route('Form', 'Supplier', res.message.name);
                                    }
                                }
                            });
                        }
                    }
                });
            })
            .css({ 
                "background-color": "#000",  // Pure black
                "color": "#fff",            // White text
                "border": "1px solid #000", // Black border
                "font-weight": "bold"       // Bold text for visibility
            });
        }
    }
});

