                                        .text(m.supplier_name)
                                        .css({
                                            padding: '6px 12px',
                                            color: '#888',
                                            cursor: 'not-allowed',
                                            'pointer-events': 'none',
                                            'font-style': 'italic'
                                        })
                                        .appendTo(dropdown);
                                });

                                dropdown
                                    .css({
                                        top: input.position().top + input.outerHeight(),
                                        left: input.position().left,
                                        width: input.outerWidth()
                                    })
                                    .show();
                            } else {
                                dropdown.hide();
                            }
                        }
                    });
                }, 300);
            });

            input.on('blur', function () {
                const raw = input.val();
                if (!raw || raw.length < 2) return;

                const formatted = format_text(raw);
                frm.set_value('supplier_name', formatted);

                const norm_input = normalize(formatted);

                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Supplier",
                        fields: ["supplier_name"],
                        limit_page_length: 1000
                    },
                    callback: function (res) {
                        const matches = (res.message || []).filter(row => {
                            const norm = normalize(row.supplier_name);
                            return (
                                norm === norm_input ||
                                norm.startsWith(norm_input) ||
                                norm.includes(norm_input)
                            );
                        });

                        if (matches.length > 0) {
                            frappe.msgprint({
                                title: "🛑 Possible Duplicate",
                                message: `A similar supplier exists: <b>${matches.map(m => m.supplier_name).join(", ")}</b><br>Please use a unique name.`,
                                indicator: 'red'
                            });
                        } else {
                            frappe.msgprint({
                                title: "✅ No Duplicate Found",
                                message: "This supplier name appears unique. Safe to proceed.",
                                indicator: 'green'
                            });
                        }
                    }
                });
            });

            $(document).on('click', function (e) {
                if (!$(e.target).closest('.supplier-suggestion-box, input[data-fieldname="supplier_name"]').length) {
                    dropdown.hide();
                }
            });
        }, 300);
    }
});

// Utility function: Capitalize each word and after hyphens
function format_text(str) {
    return str
        .toLowerCase()
        .replace(/\s{2,}/g, ' ')
        .split(/(\s+|\-)/)
        .map(word =>
            /^[a-z]/.test(word) ? word.charAt(0).toUpperCase() + word.slice(1) : word
        )
        .join('');
}

frappe.ui.form.on('Feasibility', {
    onload(frm) {
        frm.trigger('auto_format_fields');
    },

    auto_format_fields(frm) {
        const fields_to_format = ['site_name', 'description'];

        fields_to_format.forEach(fieldname => {
            setTimeout(() => {
                const input = frm.fields_dict[fieldname]?.$wrapper?.find('input');
                if (!input || input.hasClass('capitalize-attached')) return;

                input.addClass('capitalize-attached');

                const formatText = (str) => {
                    return str
                        .toLowerCase()
                        .replace(/\s{2,}/g, ' ') // collapse multiple spaces
                        .split(/(\s+|\-)/)       // split by spaces and hyphens, keep separators
                        .map(part =>
                            /^[a-z]/.test(part) ? part.charAt(0).toUpperCase() + part.slice(1) : part
                        )
                        .join('');
                };

                input.on('input', function () {
                    const cursorPos = this.selectionStart;
                    const original = this.value;
                    const formatted = formatText(original);

                    if (original !== formatted) {
                        this.value = formatted;
                        this.setSelectionRange(cursorPos, cursorPos);
                    }
                });

                input.on('blur', function () {
                    const final = formatText(this.value);
                    frm.set_value(fieldname, final);
                });

            }, 300);
        });
    }
});

