});

function calculate_row_total(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    if (!row.km || !row.mode) {
        return;  // Do nothing until both fields are set
    }

    let rate = 0;
    if (row.mode === 'Two Wheeler') {
        rate = 4;
    } else if (row.mode === 'Four Wheeler') {
        rate = 8;
    }

    const total = row.km * rate;
    frappe.model.set_value(cdt, cdn, 'total_amount', total);

    // Slight delay ensures set_value finishes before total sum
    setTimeout(() => calculate_grand_total(frm), 100);
}

function calculate_grand_total(frm) {
    let total = 0;
    (frm.doc.meetings || []).forEach(row => {
        total += parseFloat(row.total_amount) || 0;
    });

    if (total > 10000) {
        frappe.msgprint('⚠️ Grand Total cannot exceed ₹10,000. It has been capped.');
        total = 10000;
    }

    frm.set_value('grand_total', total);
}

