            else if (frm.doc.status === 'Partially Completed') {
                site_updates.provisioning_partially_completed_date = frm.doc.provisioning_partially_completed_date;
                site_updates.site_status = "Partially Provisioning Completed";
                site_updates.lms_stage = "LMS Partially Delivered";
                installation_status = "Partially Provisioning Completed";
                confirmation_message = "Do you want to update the Site and Installation Master as 'Partially Provisioning Completed'?";
