            frappe.confirm(__(confirmation_message), function() {

                // ✅ Update Site
                frappe.call({
                    method: "frappe.client.set_value",
                    args: {
                        doctype: "Site",
                        name: frm.doc.circuit_id,
                        fieldname: site_updates
                    },
                    callback: function() {
                        frappe.msgprint('✅ Site updated successfully.');
