frappe.listview_settings['Opportunity'] = {
    refresh: function(listview) {
        let rows = [...document.querySelectorAll('.list-row')];
        if (rows.length === 0) return;

        // Step 1: Get column count from first row
        let colCount = rows[0].querySelectorAll('.list-row-col').length;
        let maxWidths = new Array(colCount).fill(0);

        // Step 2: Measure max width for each column
        rows.forEach(row => {
            row.querySelectorAll('.list-row-col').forEach((col, idx) => {
                col.style.width = 'auto';
                col.style.minWidth = 'unset';
                col.style.maxWidth = 'unset';
                let width = col.offsetWidth;
                if (width > maxWidths[idx]) {
                    maxWidths[idx] = width;
                }
            });
        });

        // Step 3: Apply max width to all rows per column index
        rows.forEach(row => {
            row.querySelectorAll('.list-row-col').forEach((col, idx) => {
                col.style.minWidth = maxWidths[idx] + 'px';
                col.style.maxWidth = maxWidths[idx] + 'px';
            });
        });

        // Optional: Handle subject field separately (if present)
        document.querySelectorAll('.list-subject').forEach(subject => {
            subject.style.minWidth = '300px';
            subject.style.maxWidth = '300px';
        });

        // Step 4: Make list scrollable
        let main_container = document.querySelector('.frappe-list');
        if (main_container) {
            main_container.style.overflowX = 'auto';
        }
    }
};

