/**
 * Maps sales_stage → status, with rollback and Quotation preservation.
 */
function update_status_based_on_stage(frm) {
    const stage = frm.doc.sales_stage;
    const currentStatus = frm.doc.status;
    let newStatus = null;

    // Win stages → Closed
    if (stage === 'Close Won' || stage === 'Closed Won') {
        newStatus = 'Closed';
    }
    // Loss stages → Lost
    else if ([
        'Closed Lost to Competition',
        'Closed Drop',
        'Drop',
        'Closed'
    ].includes(stage)) {
        newStatus = 'Lost';
    }
    // Any other stage → rollback to Open (unless current status is Quotation)
    else {
        if (currentStatus !== 'Quotation') {
            newStatus = 'Open';
        }
    }

    // Apply the new status if determined
    if (newStatus) {
        frm.set_value('status', newStatus);
    }
}

