frappe.ui.form.on('Quotation', {
    refresh(frm) {
        // Bind once
        if (frm._recurring_arc_bound) return;
        frm._recurring_arc_bound = true;

        const table_fieldname = 'custom_recurring';
        const grid = frm.fields_dict[table_fieldname]?.grid;
        if (!grid) return;

        const childDT = frm.fields_dict[table_fieldname].df.options; // actual child DocType

        // Delegated listener for mrc/qty inputs (works for existing + newly added rows)
        $(grid.wrapper).on('input', 'input[data-fieldname="mrc"], input[data-fieldname="qty"]', function (e) {
            const $row = $(e.target).closest('.grid-row');
            const cdn = $row.attr('data-name');
            if (!cdn) return;

            const row = locals[childDT][cdn];
            const mrc = frappe.utils.flt(row.mrc);
            const qty = frappe.utils.flt(row.qty);
            const value = mrc * qty;

            // Works even if 'arc' is read-only
            frappe.model.set_value(childDT, cdn, 'arc', value);
        });

        // Also recalc everything on refresh (covers existing data)
        recalc_all_arc(frm, table_fieldname, childDT);
    },

    // Safety net: ensure values are correct before save
    validate(frm) {
        const table_fieldname = 'custom_recurring';
        const childDT = frm.fields_dict[table_fieldname]?.df?.options;
        if (childDT) recalc_all_arc(frm, table_fieldname, childDT);
    }
});

function recalc_all_arc(frm, table_fieldname, childDT) {
    (frm.doc[table_fieldname] || []).forEach(d => {
        const mrc = frappe.utils.flt(d.mrc);
        const qty = frappe.utils.flt(d.qty);
        const value = mrc * qty;
        frappe.model.set_value(childDT, d.name, 'arc', value);
    });
    frm.refresh_field(table_fieldname);
}

