function toggle_task_buttons(frm) {

    // Show buttons only when condition is satisfied
    if (frm.doc.custom_lms_rca === "Finance Issue" && frm.doc.custom_lms_id) {

        // CREATE TASK
        frm.add_custom_button(
            `<i class="fa fa-plus"></i> Create Task`,
            function () {
                open_task_dialog(frm);
            },
            "Task"
        );

        // TASK LIST VIEW
        frm.add_custom_button(
            `<i class="fa fa-list"></i> Task List View`,
            function () {

                let url = `/app/task?reference_name=${frm.doc.name}`;
                window.open(url, "_blank");

            },
            "Task"
        );
    }
