function open_task_dialog(frm) {

    let d = new frappe.ui.Dialog({
        title: "Create Task",
        size: "small",

        fields: [

            {
                label: "Task Type",
                fieldname: "type",
                fieldtype: "Data",
                default: "Finance Issue",
                read_only: 1
            },

            {
                label: "Task Subject",
                fieldname: "subject",
                fieldtype: "Data",
                reqd: 1
            },

            {
                label: "Task Description",
                fieldname: "description",
                fieldtype: "Small Text"
            }

        ],

        primary_action_label: "Confirm",

        primary_action(values) {

            frappe.call({
                method: "frappe.client.insert",

                args: {
                    doc: {
                        doctype: "Task",
                        type: values.type,
                        subject: values.subject,
                        description: values.description,

                        reference_type: "HD Ticket",
                        reference_name: frm.doc.name,

                        custom_lms_id: frm.doc.custom_lms_id,
                        custom_customer: frm.doc.customer
                    }
                },

                callback: function(r) {

                    if (!r.exc) {

                        frm.set_value("custom_task", r.message.name);
                        frm.set_value("custom_task_status", "Open");
                        frm.set_value("custom_task_created_datetime", frappe.datetime.now_datetime());

                        frm.save();

                        d.hide();

                        frappe.show_alert({
                            message: "Task Created Successfully",
                            indicator: "green"
                        });

                    }
                }

            });

        }

    });

    d.show();
}

frappe.ui.form.on('Lastmile Services Master', {

    onload: function (frm) {
        lock_lms_date_field(frm);
    },

    refresh: function (frm) {
        lock_lms_date_field(frm);
    },

    lms_delivery_date: function (frm) {

        if (!frm.doc.lms_delivery_date) return;

        // ✅ Administrator bypass (no restriction)
        if (frappe.session.user === "Administrator") {
            lock_lms_date_field(frm);
            return;
        }

        // Ignore back-date rule for POC Customer
        if (frm.doc.customer_type === "POC Customer") {
            lock_lms_date_field(frm);
            return;
        }

        let today = frappe.datetime.get_today();
        let allowed_back_date = frappe.datetime.add_days(today, -7);

        // Back date validation (7 days only)
        if (frm.doc.lms_delivery_date < allowed_back_date) {

            frappe.msgprint({
                title: __('Invalid Date'),
                message: __(
                    'Back date is allowed only for the last 7 days.<br>' +
                    'Allowed range: <b>{0}</b> to <b>{1}</b>.',
                    [allowed_back_date, today]
                ),
                indicator: 'red'
            });

            frm.set_value('lms_delivery_date', null);
            return;
        }

        // Lock after setting date
        lock_lms_date_field(frm);
    }
});


function lock_lms_date_field(frm) {

    // Skip for new documents
    if (frm.is_new()) return;

    // Administrator can always edit
    if (frappe.session.user === "Administrator") {
        frm.set_df_property('lms_delivery_date', 'read_only', 0);
        return;
    }

    // Lock date after save
    if (frm.doc.lms_delivery_date) {
        frm.set_df_property('lms_delivery_date', 'read_only', 1);
    }
}

frappe.ui.form.on("Task", {
    refresh: function(frm) {

        // wait for roles to load properly
        setTimeout(() => {
            setupPOCToPaidSOButton(frm);
        }, 200);

    }
});

function setupPOCToPaidSOButton(frm) {

    // remove button to avoid duplicates
    frm.remove_custom_button("Create POC To Paid SO");

    if (!shouldShowButton(frm)) return;

    const btn = frm.add_custom_button(
        "Create POC To Paid SO",
        function () {
            createSalesOrder(frm);
        }
    );

    styleButton(btn);
}

function shouldShowButton(frm) {

    const allowed_roles = [
        "accounts receivable",
        "Accounts Manager",
        "Accounts & Finance Manager"
    ];

    let has_role = false;

    if (frappe.user_roles && frappe.user_roles.length) {
        has_role = frappe.user_roles.some(role => allowed_roles.includes(role));
    }

    if (!has_role) return false;

    return (
        frm.doc.type === "Sales Order Request" &&
        frm.doc.custom_order_type === "POC To Paid" &&
        frm.doc.status === "Open"
    );
}

function createSalesOrder(frm) {

    frappe.new_doc("Sales Order", {

        customer: frm.doc.custom_customer,
        order_type: "POC To Paid",
        po_no: frm.doc.custom_purchase_order_no,
        po_date: frm.doc.custom_purchase_order_date,
        custom_customer_purchase_amount: frm.doc.custom_po_amount,
        custom_po_end_date: frm.doc.custom_po_end_date,

        // link task
        custom_task_id: frm.doc.name,

        // copy CRM deal
        custom_crm_deal: frm.doc.custom_crm_deal

    }, function(doc) {

        // remove default blank row
        doc.items = [];

        if (frm.doc.custom_circuit_id && frm.doc.custom_circuit_id.length) {

            frm.doc.custom_circuit_id.forEach(function(row) {

                let child = frappe.model.add_child(doc, "Sales Order Item", "items");

                frappe.model.set_value(child.doctype, child.name, "item_code", row.custom_product);
                frappe.model.set_value(child.doctype, child.name, "item_name", row.custom_product_name);
                frappe.model.set_value(child.doctype, child.name, "custom_feasibility", row.circuit_id);
                frappe.model.set_value(child.doctype, child.name, "custom_solution", row.solution);
                frappe.model.set_value(child.doctype, child.name, "qty", 1);
                frappe.model.set_value(child.doctype, child.name, "uom", "Nos");

            });

        }

        frappe.model.set_value(doc.doctype, doc.name, "items", doc.items);

    });
}

function styleButton(btn) {
    btn.css({
        "background-color": "black",
        "color": "white",
        "border": "none"
    });
}

