frappe.ui.form.on("Disconnection Request", {

    onload(frm) {

        let is_admin =
            frappe.session.user === "Administrator" ||
            frappe.user.has_role("System Manager");

        // If date already locked, make it readonly
        if (frm.doc.date_locked && !is_admin) {
            frm.set_df_property("notice_period_start_date", "read_only", 1);
        }

    },


    notice_period_start_date(frm) {

        if (!frm.doc.notice_period_start_date) return;

        let is_admin =
            frappe.session.user === "Administrator" ||
            frappe.user.has_role("System Manager");

        // If already edited once, stop user
        if (frm.doc.date_locked && !is_admin) {

            frappe.msgprint({
                title: "Not Allowed",
                indicator: "red",
                message: "Notice Period Start Date can be edited only once. Please contact Admin."
            });

            frm.reload_doc();
            return;
        }

        let today = frappe.datetime.get_today();
        let diff = frappe.datetime.get_day_diff(today, frm.doc.notice_period_start_date);

        // Allow only 7 days backdate
        if (diff > 7 && !is_admin) {

            frappe.msgprint({
                title: "Backdate Not Allowed",
                indicator: "red",
                message: "Backdating the Notice Period Start Date beyond 7 days is not permitted."
            });

            frm.set_value("notice_period_start_date", "");
        }

    },


    after_save(frm) {

        let is_admin =
            frappe.session.user === "Administrator" ||
            frappe.user.has_role("System Manager");

        // Lock after first save
        if (!is_admin && !frm.doc.date_locked && frm.doc.notice_period_start_date) {

            frappe.db.set_value(
                "Disconnection Request",
                frm.doc.name,
                "date_locked",
                1
            );

            frm.set_df_property("notice_period_start_date", "read_only", 1);
        }

    }

});
